INSERT INTO addon_services (
    code, name, description, monthly_fee, status
) VALUES
    ('UBOT_ADDON_CALLER', 'Ubot 발신번호 표시', '수신 전화의 발신번호 표시. 발신번호 비공개 전화는 표시하지 않음. 월 0원, 부가세 포함. 해지 전까지 월 단위 유지.', 0, 'ACTIVE'),
    ('UBOT_ADDON_SPAM', 'Ubot 스팸 차단', '스팸 의심 전화·문자 알림과 차단 설정. 정상 연락이 차단될 수 있어 목록 해제 가능. 월 0원, 부가세 포함. 해지 전까지 월 단위 유지.', 0, 'ACTIVE'),
    ('UBOT_ADDON_PAY_BLOCK', 'Ubot 휴대폰 결제 차단', '휴대폰 소액결제·콘텐츠 결제 차단. 이미 발생한 결제 취소와는 별개. 월 0원, 부가세 포함. 해지 전까지 월 단위 유지.', 0, 'ACTIVE'),
    ('UBOT_ADDON_INTL_BLOCK', 'Ubot 국제전화 발신 차단', '해외 번호로 발신하는 국제전화 차단. 국내 통화는 유지. 월 0원, 부가세 포함. 해지 전까지 월 단위 유지.', 0, 'ACTIVE'),
    ('UBOT_ADDON_ROAM_BLOCK', 'Ubot 데이터 로밍 차단', '해외 이동통신 데이터 차단. Wi-Fi와 국내 데이터는 유지. 월 0원, 부가세 포함. 해지 전까지 월 단위 유지.', 0, 'ACTIVE'),
    ('UBOT_ADDON_WAITING', 'Ubot 통화중 대기', '통화 중 걸려온 다른 전화를 알림. 지원 단말 설정 필요. 월 0원, 부가세 포함. 해지 전까지 월 단위 유지.', 0, 'ACTIVE'),
    ('UBOT_ADDON_MISSED', 'Ubot 부재중 알림', '전원 꺼짐·통화 불가 중 걸려온 전화의 수신 기록 알림. 월 550원, 부가세 포함. 해지 전까지 월 단위 유지.', 550, 'ACTIVE'),
    ('UBOT_ADDON_DUAL', 'Ubot 듀얼번호', '같은 단말에서 보조 번호 1개 이용. 데이터·통화 제공량은 주 회선에서 차감. 월 3,300원, 부가세 포함. 해지 전까지 월 단위 유지.', 3300, 'ACTIVE'),
    ('UBOT_ADDON_FORWARD', 'Ubot 착신전환', '설정한 국내 번호로 음성 전화 전환. 국제·유료 특수번호 전환 불가. 월 1,100원, 부가세 포함. 해지 전까지 월 단위 유지.', 1100, 'ACTIVE'),
    ('UBOT_ADDON_RING', 'Ubot 컬러링', '통화연결음 변경. 기본 제공 음원만 이용하며 유료 음원 별도 구매 없음. 월 990원, 부가세 포함. 해지 전까지 월 단위 유지.', 990, 'ACTIVE'),
    ('UBOT_ADDON_DATA_1', 'Ubot 데이터 플러스 1GB', '매월 1GB 추가. 매월 말 소멸·이월 불가. 일회성 충전이 아닌 월 자동 갱신 상품. 월 3,300원, 부가세 포함. 해지 전까지 월 단위 유지.', 3300, 'ACTIVE'),
    ('UBOT_ADDON_DATA_5', 'Ubot 데이터 플러스 5GB', '매월 5GB 추가. 매월 말 소멸·이월 불가. 같은 데이터 추가 팩 중복 가입 불가. 월 9,900원, 부가세 포함. 해지 전까지 월 단위 유지.', 9900, 'ACTIVE'),
    ('UBOT_ADDON_DATA_10', 'Ubot 데이터 플러스 10GB', '매월 10GB 추가. 매월 말 소멸·이월 불가. 같은 데이터 추가 팩 중복 가입 불가. 월 14,900원, 부가세 포함. 해지 전까지 월 단위 유지.', 14900, 'ACTIVE'),
    ('UBOT_ADDON_VOICE_100', 'Ubot 음성 플러스 100', '국내 일반 음성 매월 100분 추가. 국제·영상·유료 특수번호 제외, 잔여량 이월 불가. 월 3,300원, 부가세 포함. 해지 전까지 월 단위 유지.', 3300, 'ACTIVE'),
    ('UBOT_ADDON_BOOK', 'Ubot 북패스', '가상 Ubot 전자책 라이브러리 이용. 북패스 포함 요금제에는 중복 가입하지 않음. 월 4,900원, 부가세 포함. 해지 전까지 월 단위 유지.', 4900, 'ACTIVE'),
    ('UBOT_ADDON_MUSIC', 'Ubot 뮤직패스', '가상 Ubot 음악 스트리밍 이용. 데이터는 가입 요금제에서 차감. 월 6,900원, 부가세 포함. 해지 전까지 월 단위 유지.', 6900, 'ACTIVE'),
    ('UBOT_ADDON_VIDEO', 'Ubot 비디오패스', '가상 Ubot 영상 라이브러리 1인 이용. 실제 OTT 제휴 상품이 아님. 월 9,900원, 부가세 포함. 해지 전까지 월 단위 유지.', 9900, 'ACTIVE'),
    ('UBOT_ADDON_KIDS', 'Ubot 키즈가드', '보호자 연결·동의 후 자녀 위치 공유와 유해 사이트 차단. 긴급 출동 서비스는 미제공. 월 2,200원, 부가세 포함. 해지 전까지 월 단위 유지.', 2200, 'ACTIVE'),
    ('UBOT_ADDON_FAMILY', 'Ubot 패밀리 안심', '본인 동의한 가족의 안부 확인·위치 공유. 의료 진단·응급 구조 기능은 미제공. 월 3,300원, 부가세 포함. 해지 전까지 월 단위 유지.', 3300, 'ACTIVE'),
    ('UBOT_ADDON_PHISHING', 'Ubot 피싱가드', '위험 링크·의심 전화 알림. 금융 손해에 대한 보험·배상 서비스는 미제공. 월 2,200원, 부가세 포함. 해지 전까지 월 단위 유지.', 2200, 'ACTIVE'),
    ('UBOT_ADDON_DEVICE', 'Ubot 디바이스 케어', '단말 상태 점검·원격 이용 상담. 수리비 보상·분실 보험·기기 교환은 미제공. 월 4,400원, 부가세 포함. 해지 전까지 월 단위 유지.', 4400, 'ACTIVE')
