-- 부가서비스 분류
UPDATE addon_services a SET category = m.category
FROM (VALUES
    ('UBOT_ADDON_CALLER', 'CALL'), ('UBOT_ADDON_WAITING', 'CALL'), ('UBOT_ADDON_MISSED', 'CALL'),
    ('UBOT_ADDON_DUAL', 'CALL'), ('UBOT_ADDON_FORWARD', 'CALL'), ('UBOT_ADDON_RING', 'CALL'),
    ('UBOT_ADDON_SPAM', 'BLOCKING'), ('UBOT_ADDON_PAY_BLOCK', 'BLOCKING'),
    ('UBOT_ADDON_INTL_BLOCK', 'BLOCKING'), ('UBOT_ADDON_ROAM_BLOCK', 'BLOCKING'),
    ('UBOT_ADDON_DATA_1', 'DATA_CHARGE'), ('UBOT_ADDON_DATA_5', 'DATA_CHARGE'), ('UBOT_ADDON_DATA_10', 'DATA_CHARGE'),
    ('UBOT_ADDON_VOICE_100', 'VOICE_CHARGE'),
    ('UBOT_ADDON_BOOK', 'CONTENT'), ('UBOT_ADDON_MUSIC', 'CONTENT'), ('UBOT_ADDON_VIDEO', 'CONTENT'),
    ('UBOT_ADDON_KIDS', 'SAFETY'), ('UBOT_ADDON_FAMILY', 'SAFETY'), ('UBOT_ADDON_PHISHING', 'SAFETY'),
    ('UBOT_ADDON_DEVICE', 'ETC')
) AS m (code, category)
WHERE a.code = m.code;

-- 결합 종류와 회선 수 (FAQ 298, 1373, 1376~1380). 홈 500·기가 결합은 인터넷 상품이 없어 연결하지 않는다.
UPDATE bundle_products b SET bundle_type = m.bundle_type, line_count = m.line_count
FROM (VALUES
    ('UBOT_BUNDLE_FAMILY_2', 'FAMILY', 2), ('UBOT_BUNDLE_FAMILY_3', 'FAMILY', 3),
    ('UBOT_BUNDLE_FAMILY_4', 'FAMILY', 4), ('UBOT_BUNDLE_FAMILY_5', 'FAMILY', 5),
    ('UBOT_BUNDLE_LONG_TERM', 'FAMILY', NULL),
    ('UBOT_BUNDLE_PREMIUM_2', 'DUO', 2), ('UBOT_BUNDLE_YOUTH_2', 'DUO', 2),
    ('UBOT_BUNDLE_SENIOR_FAMILY', 'DUO', 2), ('UBOT_BUNDLE_KIDS_FAMILY', 'DUO', 2),
    ('UBOT_BUNDLE_FRIEND_2', 'ETC', 2), ('UBOT_BUNDLE_FRIEND_3', 'ETC', 3),
    ('UBOT_BUNDLE_WATCH', 'ETC', 2), ('UBOT_BUNDLE_TABLET', 'ETC', 2),
    ('UBOT_BUNDLE_HOME_100', 'HOME', 1), ('UBOT_BUNDLE_HOME_500', 'HOME', 1), ('UBOT_BUNDLE_HOME_1000', 'HOME', 1)
) AS m (code, bundle_type, line_count)
