UPDATE bundle_products b SET home_product_id = h.home_product_id
FROM home_products h
WHERE b.code = 'UBOT_BUNDLE_HOME_100' AND h.code = 'UBOT_HOME_INTERNET_100';

-- 요금제 포함 부가서비스 (FAQ 1113, 1116, 1119, 1343~1347)
INSERT INTO plan_included_addons (plan_id, addon_service_id)
SELECT p.plan_id, a.addon_service_id
FROM (VALUES
    ('UBOT_LIFE_01', 'UBOT_ADDON_MUSIC'), ('UBOT_LIFE_02', 'UBOT_ADDON_VIDEO'), ('UBOT_LIFE_06', 'UBOT_ADDON_PHISHING'),
    ('UBOT_BOOK_01', 'UBOT_ADDON_BOOK'), ('UBOT_BOOK_02', 'UBOT_ADDON_BOOK'),
    ('UBOT_BOOK_03', 'UBOT_ADDON_BOOK'), ('UBOT_BOOK_04', 'UBOT_ADDON_BOOK'),
    ('UBOT_KIDS_01', 'UBOT_ADDON_KIDS'), ('UBOT_KIDS_02', 'UBOT_ADDON_KIDS'),
    ('UBOT_KIDS_03', 'UBOT_ADDON_KIDS'), ('UBOT_KIDS_04', 'UBOT_ADDON_KIDS')
) AS m (plan_code, addon_code)
JOIN plans p ON p.plan_code = m.plan_code
JOIN addon_services a ON a.code = m.addon_code
ON CONFLICT DO NOTHING;
